   157→    // benchmark_soa_dot_product: SoA 점곱 벤치마크
   158→    func benchmark_soa_dot_product(element_count: u32) -> PerformanceMetric {
   159→        // 두 개의 SoA 벡터 생성
   160→        let v1 = Vector3DSoA {
   161→            x: make([f32], element_count),
   162→            y: make([f32], element_count),
   163→            z: make([f32], element_count),
   164→            count: element_count,
   165→        };
   166→
   167→        let v2 = Vector3DSoA {
   168→            x: make([f32], element_count),
   169→            y: make([f32], element_count),
   170→            z: make([f32], element_count),
   171→            count: element_count,
   172→        };
   173→
   174→        // 데이터 초기화
   175→        for j = 0; j < element_count; j = j + 1 {
   176→            v1.x[j] = 1.0;
   177→            v1.y[j] = 2.0;
   178→            v1.z[j] = 3.0;
   179→
   180→            v2.x[j] = 4.0;
   181→            v2.y[j] = 5.0;
   182→            v2.z[j] = 6.0;
   183→        }
   184→
   185→        let iterations = u64(1000);
   186→        let timer = timer_start();
   187→
   188→        for i = 0; i < iterations; i = i + 1 {
   189→            // 점곱 계산
   190→            for j = 0; j < element_count; j = j + 1 {
   191→                let dot = v1.x[j] * v2.x[j] +
   192→                          v1.y[j] * v2.y[j] +
   193→                          v1.z[j] * v2.z[j];
   194→            }
   195→        }
   196→
   197→        let elapsed = timer.timer_stop();
   198→        let elapsed_micro = elapsed / NANO_PER_MICRO;
   199→        let total_ops = iterations * u64(element_count);
   200→        let throughput = f32(total_ops) / (f32(elapsed_micro) / 1_000_000.0);
   201→        let latency = f32(elapsed_micro) / f32(total_ops);
   202→
   203→        return PerformanceMetric {
   204→            name: "SoA Dot Product",
   205→            iterations: iterations,
   206→            elapsed_time: elapsed_micro,
   207→            throughput: throughput,
   208→            latency: latency,
   209→            memory_used: u64(element_count) * 24,
   210→            cache_lines: (u64(element_count) * 8 + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE,
   211→            is_soa: true,
   212→        };
   213→    }
