     1→// ============================================================================
     2→// FVX Safety Annotations (정형 검증 - 안전성 주석)
     3→// FreeLang 구현 - 계약 기반 프로그래밍 (Design by Contract)
     4→// ============================================================================
     5→//
     6→// 목표: @require, @ensure, @invariant 주석을 통해
     7→//       함수의 사전조건(Precondition), 사후조건(Postcondition),
     8→//       불변량(Invariant)을 명시적으로 정의하고 검증
     9→//
    10→// 원리:
    11→//   - Precondition (@require): 호출자가 만족해야 할 조건
    12→//   - Postcondition (@ensure): 함수가 보장할 조건
    13→//   - Invariant (@invariant): 항상 참이어야 할 조건
    14→//   - Verification: 런타임 확인 또는 정적 증명
    15→//
    16→// 형식화:
    17→//   @require(condition) → condition == true 또는 panic
    18→//   @ensure(condition) → condition == true 또는 panic (함수 반환 전)
    19→//   @invariant(condition) → 메서드 진입/종료 시마다 검증
    20→//
    21→// 예시:
    22→//   ```freelang
    23→//   @require(ptr != 0)
    24→//   @require(size > 0)
    25→//   @ensure(return != 0)
    26→//   func allocate(size: u32) -> u64 { ... }
    27→//   ```
    28→// ============================================================================
    29→
    30→module fvx {
    31→    // ========================================================================
    32→    // 데이터 구조
    33→    // ========================================================================
    34→
    35→    // ContractViolation은 계약 위반 정보
    36→    struct ContractViolation {
    37→        violation_type: u32;    // 1=precondition, 2=postcondition, 3=invariant
    38→        function_name: string;
    39→        condition: string;
    40→        actual_value: string;
    41→        expected_value: string;
    42→        message: string;
    43→    }
    44→
    45→    // ContractChecker는 계약 검증
    46→    struct ContractChecker {
    47→        violations: [ContractViolation];
    48→        function_depth: u32;    // 함수 호출 깊이
    49→        is_checking: bool;
    50→    }
    51→
    52→    // ========================================================================
    53→    // 상수
    54→    // ========================================================================
    55→
    56→    const VIOLATION_PRECONDITION: u32 = 1;
    57→    const VIOLATION_POSTCONDITION: u32 = 2;
    58→    const VIOLATION_INVARIANT: u32 = 3;
    59→
    60→    // ========================================================================
    61→    // 기본 검증 함수
    62→    // ========================================================================
    63→
    64→    // require: 사전조건 검증
    65→    // @require(condition) → condition이 거짓이면 panic
    66→    @inline
    67→    func require(condition: bool, message: string) {
    68→        if !condition {
    69→            panic("Precondition failed: " + message);
    70→        }
    71→    }
    72→
    73→    // ensure: 사후조건 검증
    74→    // @ensure(condition) → condition이 거짓이면 panic
    75→    @inline
    76→    func ensure(condition: bool, message: string) {
    77→        if !condition {
    78→            panic("Postcondition failed: " + message);
    79→        }
    80→    }
    81→
    82→    // invariant: 불변량 검증
    83→    // @invariant(condition) → condition이 거짓이면 panic
    84→    @inline
    85→    func invariant(condition: bool, message: string) {
    86→        if !condition {
    87→            panic("Invariant violated: " + message);
    88→        }
    89→    }
    90→
    91→    // ========================================================================
    92→    // Zero-Copy DB 특화 안전성 계약
    93→    // ========================================================================
    94→
    95→    // PointerContract: 포인터 안전성 계약
    96→    struct PointerContract {
    97→        ptr: u64;
    98→        buffer_start: u64;
    99→        buffer_end: u64;
   100→    }
   101→
   102→    // verify_pointer_contract: 포인터 계약 검증
   103→    // Precondition: buffer_start < buffer_end
   104→    // Postcondition: buffer_start <= ptr <= buffer_end
   105→    func verify_pointer_contract(contract: PointerContract) -> bool {
   106→        // Precondition: 버퍼 경계가 올바르게 정의되었는가?
   107→        if contract.buffer_start >= contract.buffer_end {
   108→            panic("Precondition failed: buffer_start must be < buffer_end");
   109→        }
   110→
   111→        // Postcondition: 포인터가 범위 내인가?
   112→        let in_bounds = contract.ptr >= contract.buffer_start && contract.ptr <= contract.buffer_end;
   113→        if !in_bounds {
   114→            panic("Postcondition failed: pointer out of bounds");
   115→        }
   116→
   117→        return true;
   118→    }
   119→
   120→    // ArrayAccessContract: 배열 접근 계약
   121→    struct ArrayAccessContract {
   122→        ptr: u64;
   123→        index: u64;
   124→        element_size: u64;
   125→        array_length: u64;
   126→    }
   127→
   128→    // verify_array_access_contract: 배열 접근 계약 검증
   129→    // Precondition: index >= 0, element_size > 0
   130→    // Postcondition: ptr + (index * element_size) <= buffer_end
   131→    func verify_array_access_contract(contract: ArrayAccessContract) -> bool {
   132→        // Precondition 1: element_size > 0
   133→        if contract.element_size == 0 {
   134→            panic("Precondition failed: element_size must be > 0");
   135→        }
   136→
   137→        // Precondition 2: index < array_length
   138→        if contract.index >= contract.array_length {
   139→            panic("Precondition failed: index out of bounds");
   140→        }
   141→
   142→        // Postcondition: 계산된 주소가 유효한가?
   143→        let calculated_offset = contract.index * contract.element_size;
   144→        let calculated_ptr = contract.ptr + calculated_offset;
   145→
   146→        // 오버플로우 체크
   147→        if calculated_ptr < contract.ptr {
   148→            panic("Postcondition failed: pointer arithmetic overflow");
   149→        }
   150→
   151→        return true;
   152→    }
   153→
   154→    // MemoryAllocationContract: 메모리 할당 계약
   155→    struct MemoryAllocationContract {
   156→        size: u64;
   157→        alignment: u32;
   158→        allocated_ptr: u64;
   159→        allocated_size: u64;
   160→    }
   161→
   162→    // verify_allocation_contract: 메모리 할당 계약 검증
   163→    // Precondition: size > 0, alignment > 0 (2의 거듭제곱)
   164→    // Postcondition: 할당된 메모리가 정렬되었는가? allocated_ptr % alignment == 0
   165→    func verify_allocation_contract(contract: MemoryAllocationContract) -> bool {
   166→        // Precondition 1: size > 0
   167→        if contract.size == 0 {
   168→            panic("Precondition failed: allocation size must be > 0");
   169→        }
   170→
   171→        // Precondition 2: alignment > 0
   172→        if contract.alignment == 0 {
   173→            panic("Precondition failed: alignment must be > 0");
   174→        }
   175→
   176→        // Precondition 3: alignment이 2의 거듭제곱인가?
   177→        let is_pow2 = (contract.alignment & (contract.alignment - 1)) == 0;
   178→        if !is_pow2 {
   179→            panic("Precondition failed: alignment must be power of 2");
   180→        }
   181→
   182→        // Postcondition 1: 할당된 크기가 요청 크기 이상
   183→        if contract.allocated_size < contract.size {
   184→            panic("Postcondition failed: allocated_size < requested_size");
   185→        }
   186→
   187→        // Postcondition 2: 포인터가 정렬되었는가?
   188→        let aligned = contract.allocated_ptr % u64(contract.alignment);
   189→        if aligned != 0 {
   190→            panic("Postcondition failed: allocated pointer not aligned");
   191→        }
   192→
   193→        return true;
   194→    }
   195→
   196→    // ========================================================================
   197→    // ContractChecker
   198→    // ========================================================================
   199→
   200→    // checker_new: 새로운 검증기 생성
   201→    func checker_new() -> ContractChecker {
   202→        return ContractChecker {
   203→            violations: make([ContractViolation], 0),
   204→            function_depth: 0,
   205→            is_checking: true,
   206→        };
   207→    }
   208→
   209→    // checker_record_violation: 계약 위반 기록
   210→    func (c: *ContractChecker) checker_record_violation(
   211→        violation_type: u32,
   212→        function_name: string,
   213→        condition: string,
   214→        actual_value: string,
   215→        expected_value: string
   216→    ) {
   217→        if !c.is_checking {
   218→            return;
   219→        }
   220→
   221→        let message = if violation_type == VIOLATION_PRECONDITION {
   222→            "Precondition violated"
   223→        } else if violation_type == VIOLATION_POSTCONDITION {
   224→            "Postcondition violated"
   225→        } else {
   226→            "Invariant violated"
   227→        };
   228→
   229→        let violation = ContractViolation {
   230→            violation_type: violation_type,
   231→            function_name: function_name,
   232→            condition: condition,
   233→            actual_value: actual_value,
   234→            expected_value: expected_value,
   235→            message: message,
   236→        };
   237→
   238→        c.violations.push(violation);
   239→    }
   240→
   241→    // checker_enter_function: 함수 진입
   242→    // 불변량 검증
   243→    func (c: *ContractChecker) checker_enter_function(function_name: string) {
   244→        if !c.is_checking {
   245→            return;
   246→        }
   247→        c.function_depth = c.function_depth + 1;
   248→        // 불변량 검증 로직이 여기에 추가됨
   249→    }
   250→
   251→    // checker_exit_function: 함수 종료
   252→    // 불변량 및 사후조건 검증
   253→    func (c: *ContractChecker) checker_exit_function(function_name: string) {
   254→        if !c.is_checking {
   255→            return;
   256→        }
   257→        if c.function_depth > 0 {
   258→            c.function_depth = c.function_depth - 1;
   259→        }
   260→    }
   261→
   262→    // checker_has_violations: 계약 위반이 있는가?
   263→    func (c: *ContractChecker) checker_has_violations() -> bool {
   264→        return len(c.violations) > 0;
   265→    }
   266→
   267→    // checker_get_violations: 모든 위반 반환
   268→    func (c: *ContractChecker) checker_get_violations() -> [ContractViolation] {
   269→        return c.violations;
   270→    }
   271→
   272→    // checker_report: 위반 리포트
   273→    func (c: *ContractChecker) checker_report() {
   274→        if len(c.violations) == 0 {
   275→            print("✅ Contract Checker: All contracts verified!");
   276→            return;
   277→        }
   278→
   279→        print("❌ Contract Checker: Found " + len(c.violations) + " contract violation(s)");
   280→        print("");
   281→
   282→        for i = 0; i < len(c.violations); i = i + 1 {
   283→            let v = c.violations[i];
   284→            let type_str = if v.violation_type == VIOLATION_PRECONDITION {
   285→                "Precondition"
   286→            } else if v.violation_type == VIOLATION_POSTCONDITION {
   287→                "Postcondition"
   288→            } else {
   289→                "Invariant"
   290→            };
   291→
   292→            print("Violation #" + (i + 1) + ":");
   293→            print("  Function: " + v.function_name);
   294→            print("  Type: " + type_str);
   295→            print("  Condition: " + v.condition);
   296→            print("  Expected: " + v.expected_value);
   297→            print("  Actual: " + v.actual_value);
   298→            print("  Message: " + v.message);
   299→            print("");
   300→        }
   301→    }
