   307→    // buffer_copy: 안전한 버퍼 복사
   308→    // @require(src_ptr != 0)
   309→    // @require(dst_ptr != 0)
   310→    // @require(size > 0)
   311→    // @require(src_ptr + size <= src_end)
   312→    // @require(dst_ptr + size <= dst_end)
   313→    // @ensure(destination has been modified)
   314→    @inline
   315→    func buffer_copy(
   316→        src_ptr: u64, src_end: u64,
   317→        dst_ptr: u64, dst_end: u64,
   318→        size: u64
   319→    ) -> bool {
   320→        // Precondition: src_ptr이 0이 아닌가?
   321→        if src_ptr == 0 {
   322→            panic("Precondition failed: src_ptr must not be null");
   323→        }
   324→
   325→        // Precondition: dst_ptr이 0이 아닌가?
   326→        if dst_ptr == 0 {
   327→            panic("Precondition failed: dst_ptr must not be null");
   328→        }
   329→
   330→        // Precondition: size > 0?
   331→        if size == 0 {
   332→            panic("Precondition failed: size must be > 0");
   333→        }
   334→
   335→        // Precondition: src 범위 검증
   336→        if src_ptr + size > src_end {
   337→            panic("Precondition failed: source buffer overflow");
   338→        }
   339→
   340→        // Precondition: dst 범위 검증
   341→        if dst_ptr + size > dst_end {
   342→            panic("Precondition failed: destination buffer overflow");
   343→        }
   344→
   345→        // 실제 복사 (simulation)
   346→        // memcpy(dst_ptr, src_ptr, size);
   347→
   348→        // Postcondition: 복사가 수행되었는가?
   349→        // (실제로는 메모리 비교로 검증)
   350→
   351→        return true;
   352→    }
