     1→// ============================================================================
     2→// FVX Race Condition Detector (정형 검증 - 경쟁 상태 검출기)
     3→// FreeLang 구현 - 동시성 안전성 증명
     4→// ============================================================================
     5→//
     6→// 목표: 멀티코어 환경에서 동일한 메모리 주소에 대한 동시 쓰기가
     7→//       발생할 수 없음을 정적 분석 단계에서 확정
     8→//
     9→// 원리:
    10→//   - Happens-Before Relation: 각 메모리 접근의 타이밍 관계
    11→//   - Memory Access History: 어떤 스레드가 언제 어디에 접근했는가
    12→//   - Conflict Detection: Write-Write, Read-Write 동시성 감지
    13→//   - Ownership Model: 특정 스레드만이 메모리에 접근 가능
    14→//
    15→// 형식화:
    16→//   Access = (thread_id, address, operation, timestamp, lock_held)
    17→//   Conflict = (access1, access2) where:
    18→//     - address1 == address2 (같은 메모리 주소)
    19→//     - (op1 == WRITE || op2 == WRITE) (쓰기 포함)
    20→//     - No Synchronization (같은 lock 없음)
    21→//
    22→// 검증 목표:
    23→//   ∀(access1, access2) ∈ History.
    24→//     (addr(access1) == addr(access2) ∧ isWrite(access1 ∨ access2))
    25→//       → (happens_before(access1, access2) ∨ happens_before(access2, access1)
    26→//          ∨ same_lock(access1, access2))
    27→// ============================================================================
    28→
    29→module fvx {
    30→    // ========================================================================
    31→    // 상수
    32→    // ========================================================================
    33→
    34→    const OP_READ: u32 = 1;
    35→    const OP_WRITE: u32 = 2;
    36→    const OP_LOCK: u32 = 3;
    37→    const OP_UNLOCK: u32 = 4;
    38→
    39→    // ========================================================================
    40→    // 데이터 구조
    41→    // ========================================================================
    42→
    43→    // MemoryAccess는 메모리 접근 기록
    44→    struct MemoryAccess {
    45→        thread_id: u32;         // 접근한 스레드 ID
    46→        address: u64;           // 메모리 주소
    47→        operation: u32;         // OP_READ, OP_WRITE, OP_LOCK, OP_UNLOCK
    48→        timestamp: u64;         // 논리적 타임스탬프 (벡터 클록)
    49→        lock_id: u32;           // 보유한 락 ID (0 = 없음)
    50→        instruction_id: u64;    // 명령어 ID (프로그램 순서)
    51→        is_volatile: bool;      // volatile 변수인가?
    52→    }
    53→
    54→    // RaceCondition은 경쟁 상태 발견
    55→    struct RaceCondition {
    56→        access1: MemoryAccess;
    57→        access2: MemoryAccess;
    58→        conflict_type: u32;     // 1=Read-Write, 2=Write-Write
    59→        same_address: bool;
    60→        synchronized: bool;     // 동기화되었는가?
    61→        message: string;
    62→    }
    63→
    64→    // ThreadState는 각 스레드의 상태
    65→    struct ThreadState {
    66→        thread_id: u32;
    67→        lock_ids: [u32];        // 현재 보유한 락 목록
    68→        last_timestamp: u64;    // 마지막 접근 타임스탬프
    69→        access_count: u32;      // 총 접근 횟수
    70→    }
    71→
    72→    // LockState는 락의 상태
    73→    struct LockState {
    74→        lock_id: u32;
    75→        owner_thread: u32;      // 현재 소유 스레드 (0 = free)
    76→        acquisition_count: u32; // 획득 횟수
    77→    }
    78→
    79→    // ========================================================================
    80→    // 기본 검증 함수
    81→    // ========================================================================
    82→
    83→    // is_write_operation: 쓰기 연산인가?
    84→    @inline
    85→    func is_write_operation(op: u32) -> bool {
    86→        return op == OP_WRITE;
    87→    }
    88→
    89→    // is_read_operation: 읽기 연산인가?
    90→    @inline
    91→    func is_read_operation(op: u32) -> bool {
    92→        return op == OP_READ;
    93→    }
    94→
    95→    // is_sync_operation: 동기화 연산인가? (락)
    96→    @inline
    97→    func is_sync_operation(op: u32) -> bool {
    98→        return op == OP_LOCK || op == OP_UNLOCK;
    99→    }
   100→
   101→    // same_lock: 두 접근이 같은 락으로 보호되는가?
   102→    @inline
   103→    func same_lock(lock1: u32, lock2: u32) -> bool {
   104→        return lock1 != 0 && lock1 == lock2;
   105→    }
   106→
   107→    // ========================================================================
   108→    // Happens-Before 관계
   109→    // ========================================================================
   110→
   111→    // happens_before: access1이 access2보다 논리적으로 먼저 일어났는가?
   112→    // 조건:
   113→    //   1. 같은 스레드 내: instruction_id 비교
   114→    //   2. 다른 스레드: synchronization point 추적
   115→    @inline
   116→    func happens_before(a1: MemoryAccess, a2: MemoryAccess) -> bool {
   117→        // 같은 스레드 내에서는 instruction_id로 비교
   118→        if a1.thread_id == a2.thread_id {
   119→            return a1.instruction_id < a2.instruction_id;
   120→        }
   121→
   122→        // 다른 스레드: 타임스탬프로 비교 (vector clock simulation)
   123→        return a1.timestamp < a2.timestamp;
   124→    }
   125→
   126→    // ========================================================================
   127→    // 경쟁 상태 감지
   128→    // ========================================================================
   129→
   130→    // has_data_race: 두 접근 사이에 경쟁 상태가 있는가?
   131→    func has_data_race(a1: MemoryAccess, a2: MemoryAccess) -> bool {
   132→        // 조건 1: 같은 메모리 주소
   133→        if a1.address != a2.address {
   134→            return false;
   135→        }
   136→
   137→        // 조건 2: 둘 다 volatile 변수가 아님 (volatile은 race 없음)
   138→        if a1.is_volatile && a2.is_volatile {
   139→            return false;
   140→        }
   141→
   142→        // 조건 3: 적어도 하나는 쓰기
   143→        let is_conflict = is_write_operation(a1.operation) || is_write_operation(a2.operation);
   144→        if !is_conflict {
   145→            return false;  // 읽기-읽기는 race 아님
   146→        }
   147→
   148→        // 조건 4: 같은 락으로 보호되지 않음
   149→        if same_lock(a1.lock_id, a2.lock_id) {
   150→            return false;  // 같은 락으로 보호됨
   151→        }
   152→
   153→        // 조건 5: happens-before 관계가 없음 (동시성)
   154→        let a1_before_a2 = happens_before(a1, a2);
   155→        let a2_before_a1 = happens_before(a2, a1);
   156→
   157→        if a1_before_a2 || a2_before_a1 {
   158→            return false;  // happens-before 관계 있음
   159→        }
   160→
   161→        // 모든 조건 위반 → 경쟁 상태 있음
   162→        return true;
   163→    }
   164→
   165→    // ========================================================================
   166→    // Race Detector
   167→    // ========================================================================
   168→
   169→    // RaceDetector는 실행 중 경쟁 상태를 감지
   170→    struct RaceDetector {
   171→        accesses: [MemoryAccess];           // 모든 메모리 접근 기록
   172→        races: [RaceCondition];             // 발견된 경쟁 상태
   173→        thread_states: [ThreadState];       // 각 스레드의 상태
   174→        lock_states: [LockState];           // 락 상태
   175→        is_detecting: bool;                 // 감지 중인가?
   176→    }
   177→
   178→    // detector_new: 새로운 감지기 생성
   179→    func detector_new() -> RaceDetector {
   180→        return RaceDetector {
   181→            accesses: make([MemoryAccess], 0),
   182→            races: make([RaceCondition], 0),
   183→            thread_states: make([ThreadState], 0),
   184→            lock_states: make([LockState], 0),
   185→            is_detecting: true,
   186→        };
   187→    }
   188→
   189→    // detector_register_thread: 스레드 등록
   190→    func (d: *RaceDetector) detector_register_thread(thread_id: u32) -> bool {
   191→        if !d.is_detecting {
   192→            return false;
   193→        }
   194→
   195→        let state = ThreadState {
   196→            thread_id: thread_id,
   197→            lock_ids: make([u32], 0),
   198→            last_timestamp: 0,
   199→            access_count: 0,
   200→        };
   201→
   202→        d.thread_states.push(state);
   203→        return true;
   204→    }
   205→
   206→    // detector_register_lock: 락 등록
   207→    func (d: *RaceDetector) detector_register_lock(lock_id: u32) -> bool {
   208→        if !d.is_detecting {
   209→            return false;
   210→        }
   211→
   212→        let state = LockState {
   213→            lock_id: lock_id,
   214→            owner_thread: 0,
   215→            acquisition_count: 0,
   216→        };
   217→
   218→        d.lock_states.push(state);
   219→        return true;
   220→    }
   221→
   222→    // detector_record_access: 메모리 접근 기록
   223→    func (d: *RaceDetector) detector_record_access(
   224→        thread_id: u32,
   225→        address: u64,
   226→        operation: u32,
   227→        lock_id: u32,
   228→        is_volatile: bool
   229→    ) -> bool {
   230→        if !d.is_detecting {
   231→            return false;
   232→        }
   233→
   234→        // 타임스탬프 계산 (벡터 클록 단순화)
   235→        let timestamp = u64(len(d.accesses));
   236→
   237→        let access = MemoryAccess {
   238→            thread_id: thread_id,
   239→            address: address,
   240→            operation: operation,
   241→            timestamp: timestamp,
   242→            lock_id: lock_id,
   243→            instruction_id: u64(len(d.accesses)),
   244→            is_volatile: is_volatile,
   245→        };
   246→
   247→        d.accesses.push(access);
   248→
   249→        // 이전 접근들과 비교하여 경쟁 상태 검출
   250→        for i = 0; i < len(d.accesses) - 1; i = i + 1 {
   251→            let prev_access = d.accesses[i];
   252→
   253→            if has_data_race(prev_access, access) {
   254→                let race = RaceCondition {
   255→                    access1: prev_access,
   256→                    access2: access,
   257→                    conflict_type: if is_write_operation(prev_access.operation) &&
   258→                                      is_write_operation(access.operation) { 2 } else { 1 },
   259→                    same_address: true,
   260→                    synchronized: false,
   261→                    message: "Data race detected",
   262→                };
   263→
   264→                d.races.push(race);
   265→            }
   266→        }
   267→
   268→        return true;
   269→    }
   270→
   271→    // detector_acquire_lock: 락 획득 기록
   272→    func (d: *RaceDetector) detector_acquire_lock(thread_id: u32, lock_id: u32) -> bool {
   273→        if !d.is_detecting {
   274→            return false;
   275→        }
   276→
   277→        // 스레드 상태 업데이트
   278→        for i = 0; i < len(d.thread_states); i = i + 1 {
   279→            if d.thread_states[i].thread_id == thread_id {
   280→                d.thread_states[i].lock_ids.push(lock_id);
   281→                break;
   282→            }
   283→        }
   284→
   285→        // 락 상태 업데이트
   286→        for i = 0; i < len(d.lock_states); i = i + 1 {
   287→            if d.lock_states[i].lock_id == lock_id {
   288→                d.lock_states[i].owner_thread = thread_id;
   289→                d.lock_states[i].acquisition_count = d.lock_states[i].acquisition_count + 1;
   290→                break;
   291→            }
   292→        }
   293→
   294→        // 동기화 이벤트 기록
   295→        return d.detector_record_access(thread_id, 0, OP_LOCK, lock_id, false);
   296→    }
   297→
   298→    // detector_release_lock: 락 해제 기록
   299→    func (d: *RaceDetector) detector_release_lock(thread_id: u32, lock_id: u32) -> bool {
   300→        if !d.is_detecting {
   301→            return false;
   302→        }
   303→
   304→        // 스레드 상태 업데이트 (간단한 구현)
   305→        for i = 0; i < len(d.thread_states); i = i + 1 {
   306→            if d.thread_states[i].thread_id == thread_id {
   307→                // lock_ids에서 제거 (간단한 방식)
   308→                break;
   309→            }
   310→        }
   311→
   312→        // 락 상태 업데이트
   313→        for i = 0; i < len(d.lock_states); i = i + 1 {
   314→            if d.lock_states[i].lock_id == lock_id {
   315→                d.lock_states[i].owner_thread = 0;
   316→                break;
   317→            }
   318→        }
   319→
   320→        // 동기화 이벤트 기록
   321→        return d.detector_record_access(thread_id, 0, OP_UNLOCK, lock_id, false);
   322→    }
   323→
   324→    // detector_get_races: 발견된 경쟁 상태 반환
   325→    func (d: *RaceDetector) detector_get_races() -> [RaceCondition] {
   326→        return d.races;
   327→    }
   328→
   329→    // detector_has_races: 경쟁 상태가 있는가?
   330→    func (d: *RaceDetector) detector_has_races() -> bool {
   331→        return len(d.races) > 0;
   332→    }
   333→
   334→    // detector_report: 경쟁 상태 리포트
   335→    func (d: *RaceDetector) detector_report() {
   336→        if len(d.races) == 0 {
   337→            print("✅ Race Detector: No data races detected!");
   338→            print("");
   339→            print("   Summary:");
   340→            print("   - Total accesses: " + len(d.accesses));
   341→            print("   - Threads: " + len(d.thread_states));
   342→            print("   - Locks: " + len(d.lock_states));
   343→            return;
   344→        }
   345→
   346→        print("❌ Race Detector: Found " + len(d.races) + " potential data race(s)");
   347→        print("");
   348→
   349→        for i = 0; i < len(d.races); i = i + 1 {
   350→            let race = d.races[i];
   351→            print("Race #" + (i + 1) + ":");
   352→            print("  Address: " + race.access1.address);
   353→            print("  Thread 1: " + race.access1.thread_id);
   354→            print("    Operation: " + race.access1.operation);
   355→            print("    Lock: " + race.access1.lock_id);
   356→            print("  Thread 2: " + race.access2.thread_id);
   357→            print("    Operation: " + race.access2.operation);
   358→            print("    Lock: " + race.access2.lock_id);
   359→            print("  Type: " + if race.conflict_type == 1 { "Read-Write" } else { "Write-Write" });
   360→            print("  Message: " + race.message);
   361→            print("");
   362→        }
   363→    }
   364→
   365→    // ========================================================================
   366→    // 정적 분석: 소유권 모델
   367→    // ========================================================================
   368→
   369→    // OwnershipModel은 메모리 소유권을 추적
   370→    struct OwnershipModel {
   371→        address: u64;           // 메모리 주소
   372→        owner_thread: u32;      // 소유 스레드
   373→        access_lock: u32;       // 접근 보호 락
   374→        exclusive: bool;        // 배타적 소유인가?
   375→        is_owned: bool;         // 소유되고 있는가?
   376→    }
   377→
   378→    // verify_ownership: 메모리 소유권 검증
   379→    // → 특정 스레드만이 메모리에 접근 가능
   380→    func verify_ownership(access: MemoryAccess, ownership: OwnershipModel) -> bool {
   381→        // 조건 1: 소유되지 않은 메모리
   382→        if !ownership.is_owned {
   383→            return true;  // 누구나 접근 가능 (공유 메모리)
   384→        }
   385→
   386→        // 조건 2: 배타적 소유 → 소유자만 접근
   387→        if ownership.exclusive {
   388→            return access.thread_id == ownership.owner_thread;
   389→        }
   390→
   391→        // 조건 3: 같은 락으로 보호되는가?
   392→        if ownership.access_lock != 0 {
   393→            return access.lock_id == ownership.access_lock;
   394→        }
   395→
   396→        return true;
   397→    }
   398→}
