## 모듈 3: `stdlib/io.fl` (250-300줄)

### 핵심 설계 원칙

FreeLang은 OS 시스템 콜을 직접 호출할 수 없으므로 **모의(stub) 구조**로 작성합니다. 이 패턴은 기존 `aligned_allocator.fl`의 `virtual_alloc()`, `virtual_free()` 함수가 이미 사용한 방식입니다. 각 함수는 실제 구현 주석과 함께 시스템 연동 지점을 명시합니다.

### 핵심 구조체

```fl
module io {
    // 에러 코드 상수
    const ERR_OK:         i32 = 0;
    const ERR_NOT_FOUND:  i32 = 1;
    const ERR_PERMISSION: i32 = 2;
    const ERR_IO:         i32 = 3;

    // 파일 작업 결과 컨텍스트
    struct FileResult {
        success: bool;
        error_code: i32;
        bytes_processed: u64;
    }

    // 디렉토리 항목
    struct DirEntry {
        name:  string;
        is_dir: bool;
        size:   u64;
    }
}
```

### 주요 함수 시그니처 및 의사코드

**내부 OS 브리지 함수 (하단 배치)**
```
func sys_read_file(path: string) -> (string, i32)
    // 실제 구현: Linux open()+read()+close() 시스템 콜
    // 현재: 모의 구현 - 빈 문자열 + ERR_NOT_FOUND 반환
    // 런타임이 이 함수를 오버라이드하여 실제 파일 읽기

func sys_write_file(path: string, content: string, append: bool) -> i32
    // 실제 구현: open(O_WRONLY|O_CREAT) + write() + close()

func sys_file_exists(path: string) -> bool
    // 실제 구현: access(path, F_OK)

func sys_list_dir(path: string) -> ([string], i32)
    // 실제 구현: opendir()/readdir()/closedir()
```

**공개 API**
```
func read_file(path: string) -> (string, bool)
    if len(path) == 0 → return ("", false)
    let content, err = sys_read_file(path)
    return (content, err == ERR_OK)

func write_file(path: string, content: string) -> bool
    if len(path) == 0 → return false
    let err = sys_write_file(path, content, false)
    return err == ERR_OK

func append_file(path: string, content: string) -> bool
    let err = sys_write_file(path, content, true)
    return err == ERR_OK

func file_exists(path: string) -> bool
    if len(path) == 0 → return false
    return sys_file_exists(path)

func read_lines(path: string) -> ([string], bool)
    let content, ok = read_file(path)
    if !ok → return (make([string], 0), false)
    let lines = split_lines(content)    // '\n' 기준 분할
    return (lines, true)

func list_dir(path: string) -> ([string], bool)
    if len(path) == 0 → return (make([string], 0), false)
    let entries, err = sys_list_dir(path)
    return (entries, err == ERR_OK)
```

**내부 헬퍼**
```
@inline func split_lines(content: string) -> [string]
    // content를 '\n' 기준으로 분할
    lines = make([string], 0)
    current = ""
    for each char in content:
        if char == '\n' → lines.push(current); current = ""
        else → current += char
    if len(current) > 0 → lines.push(current)
    return lines

// FreeLang 문자열 순회: 문자 코드 접근 방식 필요
// 기존 코드에서 확인된 패턴: string을 직접 인덱싱하거나
// 내장 함수로 처리 (런타임 의존)
```

**경로 헬퍼**
```
func join_path(dir: string, file: string) -> string
    if len(dir) == 0 → return file
    // dir 마지막 문자가 '/' 이면 그대로, 아니면 '/' 추가
    return dir + "/" + file

func basename(path: string) -> string
    // '/' 이후 마지막 세그먼트 반환

func dirname(path: string) -> string
