## 모듈 4: `stdlib/concurrent.fl` (450-500줄)

### 핵심 설계 원칙

FreeLang의 실행 모델에는 OS 스레드 개념이 없습니다. 기존 `race_detector.fl`에서 `thread_id`, `MemoryAccess`, `LockState`를 다루는 방식을 분석한 결과, **협동 스케줄러 시뮬레이션 모델**을 채택합니다. 이는 v4-concurrency의 채널 기반 액터 모델 철학을 FreeLang의 단일 스레드 실행 환경에 맞게 구현한 것입니다.

실행 방식: 모든 액터는 실행 대기열(`run_queue`)에 등록되고, `scheduler.tick()`을 호출할 때마다 한 단계씩 진행됩니다. 채널은 링 버퍼(`[i64]` + 두 개의 커서) 구조입니다.

### 핵심 구조체

```fl
module concurrent {
    // 채널/액터 상태 상수
    const CHAN_OPEN:   i32 = 0;
    const CHAN_CLOSED: i32 = 1;
    const ACTOR_READY:   i32 = 0;
    const ACTOR_RUNNING: i32 = 1;
    const ACTOR_DONE:    i32 = 2;
    const ACTOR_BLOCKED: i32 = 3;

    // 채널: 링 버퍼 기반 메시지 큐
    struct Channel {
        buffer:    [i64];       // 링 버퍼 데이터
        capacity:  i32;         // 버퍼 용량
        head:      i32;         // 읽기 커서
        tail:      i32;         // 쓰기 커서
        count:     i32;         // 현재 메시지 수
        state:     i32;         // CHAN_OPEN / CHAN_CLOSED
        id:        i32;         // 채널 고유 ID
    }

    // 액터: 실행 단위
    struct Actor {
        id:         i32;
        state:      i32;        // ACTOR_READY/RUNNING/DONE/BLOCKED
        result:     i64;        // 완료 후 반환 값
        inbox:      Channel;    // 수신 전용 채널
        tick_count: i32;        // 실행된 tick 수 (디버그용)
    }

    // 스케줄러: 전역 실행 관리자
    struct Scheduler {
        actors:       [Actor];
        next_id:      i32;
        total_ticks:  i32;
    }
}
```

### 주요 함수 시그니처 및 의사코드

**채널 함수**
```
func chan_new(buffer_size: i32) -> Channel
    if buffer_size <= 0 → buffer_size = 1
    return Channel{
        buffer:   make([i64], buffer_size),
        capacity: buffer_size,
        head: 0, tail: 0, count: 0,
        state: CHAN_OPEN,
        id: monotonic_id()
    }

func (ch: *Channel) chan_send(msg: i64) -> bool
    if ch.state == CHAN_CLOSED → return false    // 닫힌 채널 거부
    if ch.count >= ch.capacity → return false   // 버퍼 가득 참 (블로킹 생략)
    ch.buffer[ch.tail] = msg
    ch.tail = (ch.tail + 1) % ch.capacity
    ch.count = ch.count + 1
    return true

func (ch: *Channel) chan_recv() -> (i64, bool)
    if ch.count == 0 →
        if ch.state == CHAN_CLOSED → return (0, false)
        return (0, false)    // 빈 채널
    let msg = ch.buffer[ch.head]
    ch.head = (ch.head + 1) % ch.capacity
    ch.count = ch.count - 1
    return (msg, true)

func (ch: *Channel) chan_close()
    ch.state = CHAN_CLOSED

@inline func (ch: *Channel) chan_is_empty() -> bool
    return ch.count == 0

@inline func (ch: *Channel) chan_is_full() -> bool
    return ch.count >= ch.capacity

@inline func (ch: *Channel) chan_len() -> i32
    return ch.count
```

**액터 함수**
```
func actor_new(id: i32, buffer_size: i32) -> Actor
    return Actor{
        id: id,
        state: ACTOR_READY,
        result: 0,
        inbox: chan_new(buffer_size),
        tick_count: 0,
    }

func (a: *Actor) actor_send(msg: i64) -> bool
    // 이 액터의 inbox에 메시지 전송
    return a.inbox.chan_send(msg)

func (a: *Actor) actor_recv() -> (i64, bool)
    // 이 액터의 inbox에서 메시지 수신
    return a.inbox.chan_recv()

func (a: *Actor) actor_tick() -> bool
    // 액터 한 스텝 실행 (협동 실행 시뮬레이션)
    if a.state == ACTOR_DONE → return false
    if a.state == ACTOR_BLOCKED && a.inbox.chan_is_empty() → return false
    a.state = ACTOR_RUNNING
    a.tick_count = a.tick_count + 1
    // 실제 구현에서 런타임이 등록된 fn 콜백 호출
    return true

func (a: *Actor) actor_finish(result: i64)
    a.result = result
    a.state = ACTOR_DONE
    a.inbox.chan_close()

func (a: *Actor) actor_is_done() -> bool
    return a.state == ACTOR_DONE
```

**스케줄러 / 공개 API**
```
func scheduler_new() -> Scheduler
    return Scheduler{
        actors: make([Actor], 0),
        next_id: 1,
        total_ticks: 0,
    }

func (s: *Scheduler) spawn(buffer_size: i32) -> i32
    // 새 액터 등록, 액터 ID 반환
    let id = s.next_id; s.next_id++
    let actor = actor_new(id, buffer_size)
    s.actors.push(actor)
    return id

func (s: *Scheduler) send(actor_id: i32, msg: i64) -> bool
    for i: if s.actors[i].id == actor_id → return s.actors[i].actor_send(msg)
    return false

func (s: *Scheduler) recv(actor_id: i32) -> (i64, bool)
    for i: if s.actors[i].id == actor_id → return s.actors[i].actor_recv()
    return (0, false)

func (s: *Scheduler) tick() -> i32
    // 전체 액터 한 라운드 실행, 활성 액터 수 반환
    let active = 0
    for i: if s.actors[i].actor_tick() → active++
    s.total_ticks++
    return active

func (s: *Scheduler) wait(actor_id: i32, max_ticks: i32) -> (i64, bool)
    // max_ticks 동안 tick()을 반복하며 해당 액터 완료 대기
    for t = 0; t < max_ticks; t++:
        for i: if s.actors[i].id == actor_id && actors[i].actor_is_done():
            return (s.actors[i].result, true)
        s.tick()
    return (0, false)   // 타임아웃

func (s: *Scheduler) finish(actor_id: i32, result: i64)
    // 외부에서 액터 완료 처리 (결과 주입)
    for i: if s.actors[i].id == actor_id → s.actors[i].actor_finish(result)

func (s: *Scheduler) stats() -> string
    // 액터 상태 요약 문자열 반환
```

**select 패턴 (채널 멀티플렉서)**
```
struct SelectResult {
    channel_idx: i32;   // 어느 채널에서 수신했는가
    value:       i64;
    ok:          bool;
}

func chan_select(channels: [Channel]) -> SelectResult
    // 첫 번째로 메시지가 있는 채널에서 수신
    for i: if !channels[i].chan_is_empty():
        let val, ok = channels[i].chan_recv()
        return SelectResult{ channel_idx: i, value: val, ok: ok }
    return SelectResult{ channel_idx: -1, value: 0, ok: false }
```

**글로벌 편의 함수 (race_detector.fl 패턴 참고)**
```
